import{s as l}from"./supabase.Cy8mvTLb.js";document.querySelectorAll(".newsletter-form").forEach(t=>{const e=t.parentElement.querySelector(".form-status"),a=t.querySelector("button");t.addEventListener("submit",async r=>{r.preventDefault();const s=t.elements.namedItem("email").value.trim();if(e.className="form-status",!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s)){e.textContent="Mohon masukkan alamat email yang valid.",e.classList.add("err");return}a.disabled=!0,a.innerHTML='<span class="spinner"></span> Mengirim';const{error:n}=await l.from("newsletter_subscribers").insert({email:s});if(a.disabled=!1,a.textContent="Berlangganan",n&&n.code!=="23505"){e.textContent="Maaf, terjadi kendala. Silakan coba lagi sebentar lagi.",e.classList.add("err");return}e.textContent="Terima kasih. Email Anda sudah tercatat.",e.classList.add("ok"),t.reset()})});
